3	/**
4	 * Resolved security policy for a route, returned by {@link RouteSecurityPolicyResolver}.
5	 */
6	public class RouteSecurityPolicy {
7	
8		private final AuthMode authMode;
9	
10		private final String matchedRuleId;
11	
12		public RouteSecurityPolicy(AuthMode authMode, String matchedRuleId) {
13			this.authMode = authMode;
14			this.matchedRuleId = matchedRuleId;
15		}
16	
17		public AuthMode getAuthMode() {
18			return authMode;
19		}
20	
21		public String getMatchedRuleId() {
22			return matchedRuleId;
23		}
24	
25		@Override
26		public String toString() {
27			return authMode + " [" + matchedRuleId + "]";
28		}
29	
30		@Override
31		public boolean equals(Object o) {
32			if (this == o) return true;
33			if (!(o instanceof RouteSecurityPolicy that)) return false;
34			return authMode == that.authMode && matchedRuleId.equals(that.matchedRuleId);
35		}
36	
37		@Override
38		public int hashCode() {
39			return 31 * authMode.hashCode() + matchedRuleId.hashCode();
40		}
41	}
