50	    @Override
51	    public void afterPropertiesSet() {
52	        if (defaultAuthMode == AuthMode.JWT_AND_HMAC) {
53	            throw new IllegalStateException(
54	                    "maritime.gateway.security.default-auth-mode=JWT_AND_HMAC is reserved and not yet implemented");
55	        }
56	        for (RoutePolicy rp : routes) {
57	            if (rp.authMode == AuthMode.JWT_AND_HMAC) {
58	                throw new IllegalStateException(
59	                        "Route '" + rp.id + "' uses JWT_AND_HMAC which is reserved and not yet implemented");
60	            }
61	        }
62	        if (jwt.enabled) {
63	            if (jwt.secret == null || jwt.secret.isBlank()) {
64	                throw new IllegalStateException(
65	                        "maritime.gateway.security.jwt.secret must not be blank when jwt.enabled=true");
66	            }
67	            if (jwt.issuer == null || jwt.issuer.isBlank()) {
68	                throw new IllegalStateException(
69	                        "maritime.gateway.security.jwt.issuer must not be blank when jwt.enabled=true");
70	            }
71	        }
72	        if (hmac.enabled) {
73	            if (hmac.timestampTolerance == null || hmac.timestampTolerance.isNegative()) {
74	                throw new IllegalStateException(
75	                        "maritime.gateway.security.hmac.timestamp-tolerance must be a positive duration when hmac.enabled=true");
76	            }
77	            if (hmac.nonceTtl == null || hmac.nonceTtl.isNegative()) {
78	                throw new IllegalStateException(
79	                        "maritime.gateway.security.hmac.nonce-ttl must be a positive duration when hmac.enabled=true");
80	            }
81	        }
82	    }
