1	package com.maritime.platform.gateway.security;
2	
3	import java.util.ArrayList;
4	import java.util.Collections;
5	import java.util.HashSet;
6	import java.util.List;
7	import java.util.Locale;
8	import java.util.Set;
9	
10	import org.springframework.beans.factory.InitializingBean;
11	import org.springframework.beans.factory.annotation.Autowired;
12	import org.springframework.http.server.reactive.ServerHttpRequest;
13	import org.springframework.stereotype.Component;
14	import org.springframework.web.util.pattern.PathPattern;
15	import org.springframework.web.util.pattern.PathPatternParser;
16	import org.springframework.web.util.pattern.PatternParseException;
17	
18	@Component
19	public class RouteSecurityPolicyResolver implements InitializingBean {
20	
21		private final GatewaySecurityProperties properties;
22	
23		private final List<GatewaySecurityPolicyCustomizer> customizers;
24	
25		private final List<String> programmaticPublicPaths = new ArrayList<>();
26	
27		private final List<ProgrammaticRouteRule> programmaticRoutes = new ArrayList<>();
28	
29		private List<CompiledPublicPath> compiledPublicPaths = Collections.emptyList();
30	
31		private List<CompiledRouteRule> compiledRoutes = Collections.emptyList();
32	
33		private AuthMode defaultAuthMode;
34	
35		private volatile boolean initialized;
36	
37		public RouteSecurityPolicyResolver(GatewaySecurityProperties properties) {
38			this(properties, Collections.emptyList());
39		}
40	
41		@Autowired
42		public RouteSecurityPolicyResolver(GatewaySecurityProperties properties,
43		                                   List<GatewaySecurityPolicyCustomizer> customizers) {
44			this.properties = properties;
45			this.customizers = customizers != null ? customizers : Collections.emptyList();
46		}
47	
48		// ---------- programmatic registration (for customizers) ----------
49	
50		public void addPublicPath(String publicPath) {
51			checkNotInitialized();
52			programmaticPublicPaths.add(publicPath);
53		}
54	
55		public void addRoutePolicy(String id, List<String> paths, List<String> methods, AuthMode authMode) {
56			checkNotInitialized();
57			if (authMode == AuthMode.JWT_AND_HMAC) {
58				throw new IllegalArgumentException(
59						"Route '" + id + "' uses JWT_AND_HMAC which is reserved and not yet implemented");
60			}
61			programmaticRoutes.add(new ProgrammaticRouteRule(id, paths, methods, authMode));
62		}
63	
64		// ---------- resolution ----------
65	
66		public RouteSecurityPolicy resolve(ServerHttpRequest request) {
67			return resolve(request.getURI().getPath(), request.getMethod() != null ? request.getMethod().name() : null);
68		}
69	
70		public RouteSecurityPolicy resolve(String path, String httpMethod) {
71			if (!initialized) {
72				compile();
73			}
74			// 1. Public paths take absolute priority — always NONE
75			for (CompiledPublicPath cpp : compiledPublicPaths) {
76				if (cpp.pattern.matches(PathContainerAdapter.parse(path))) {
77					return new RouteSecurityPolicy(AuthMode.NONE, cpp.ruleId);
78				}
79			}
80			// 2. Route policies
81			for (CompiledRouteRule crr : compiledRoutes) {
82				if (crr.matches(path, httpMethod)) {
83					return new RouteSecurityPolicy(crr.authMode, crr.ruleId);
84				}
85			}
86			// 3. Default
87			return new RouteSecurityPolicy(defaultAuthMode, "DEFAULT");
88		}
89	
90		public AuthMode getDefaultAuthMode() {
91			return defaultAuthMode;
92		}
93	
94		// ---------- initialization ----------
95	
96		@Override
97		public void afterPropertiesSet() {
98			compile();
99		}
100	
101		private void compile() {
102			if (initialized) {
103				return;
104			}
105			PathPatternParser parser = new PathPatternParser();
106			parser.setMatchOptionalTrailingSeparator(true);
107	
108			List<CompiledPublicPath> publicPatterns = new ArrayList<>();
109			List<CompiledRouteRule> routeRules = new ArrayList<>();
110	
111			// Apply customizers to collect programmatic registrations
112			for (GatewaySecurityPolicyCustomizer customizer : customizers) {
113				customizer.customize(this);
114			}
115	
116			// Compile public paths from properties
117			for (String path : properties.getPublicPaths()) {
118				publicPatterns.add(new CompiledPublicPath(compilePattern(parser, path), "PUBLIC:" + path));
119			}
120			// Compile programmatic public paths
121			for (String path : programmaticPublicPaths) {
122				publicPatterns.add(new CompiledPublicPath(compilePattern(parser, path), "PUBLIC(custom):" + path));
123			}
124	
125			// Compile route policies from properties
126			for (GatewaySecurityProperties.RoutePolicy rp : properties.getRoutes()) {
127				Set<String> methods = uppercaseSet(rp.getMethods());
128				for (String path : rp.getPaths()) {
129					routeRules.add(new CompiledRouteRule(
130							compilePattern(parser, path), rp.getId(), methods, rp.getAuthMode()));
131				}
132			}
133			// Compile programmatic route policies
134			for (ProgrammaticRouteRule pr : programmaticRoutes) {
135				Set<String> methods = uppercaseSet(pr.methods);
136				for (String path : pr.paths) {
137					routeRules.add(new CompiledRouteRule(
138							compilePattern(parser, path), pr.id, methods, pr.authMode));
139				}
140			}
141	
142			this.compiledPublicPaths = Collections.unmodifiableList(publicPatterns);
143			this.compiledRoutes = Collections.unmodifiableList(routeRules);
144			this.defaultAuthMode = properties.getDefaultAuthMode();
145			this.initialized = true;
146		}
147	
148		private static PathPattern compilePattern(PathPatternParser parser, String pattern) {
149			try {
150				return parser.parse(pattern);
151			} catch (PatternParseException e) {
152				throw new IllegalStateException("Invalid path pattern '" + pattern + "': " + e.getMessage(), e);
153			}
154		}
155	
156		private static Set<String> uppercaseSet(List<String> values) {
157			if (values == null || values.isEmpty()) {
158				return Collections.emptySet();
159			}
160			Set<String> set = new HashSet<>(values.size());
161			for (String v : values) {
162				if (v != null && !v.isBlank()) {
163					set.add(v.strip().toUpperCase(Locale.ROOT));
164				}
165			}
166			return Collections.unmodifiableSet(set);
167		}
168	
169		private void checkNotInitialized() {
170			if (initialized) {
171				throw new IllegalStateException(
172						"RouteSecurityPolicyResolver is already initialized. " +
173						"addPublicPath / addRoutePolicy must be called from a GatewaySecurityPolicyCustomizer.");
174			}
175		}
176	
177		// ---------- internal types ----------
178	
179		private static class CompiledPublicPath {
180			final PathPattern pattern;
181			final String ruleId;
182	
183			CompiledPublicPath(PathPattern pattern, String ruleId) {
184				this.pattern = pattern;
185				this.ruleId = ruleId;
186			}
187		}
188	
189		private static class CompiledRouteRule {
190			final PathPattern pattern;
191			final String ruleId;
192			final Set<String> methods;
193			final AuthMode authMode;
194	
195			CompiledRouteRule(PathPattern pattern, String ruleId, Set<String> methods, AuthMode authMode) {
196				this.pattern = pattern;
197				this.ruleId = ruleId;
198				this.methods = methods;
199				this.authMode = authMode;
200			}
201	
202			boolean matches(String path, String httpMethod) {
203				if (!this.pattern.matches(PathContainerAdapter.parse(path))) {
204					return false;
205				}
206				if (methods.isEmpty()) {
207					return true;
208				}
209				if (httpMethod == null) {
210					return false;
211				}
212				return methods.contains(httpMethod.toUpperCase(Locale.ROOT));
213			}
214		}
215	
216		private static class ProgrammaticRouteRule {
217			final String id;
218			final List<String> paths;
219			final List<String> methods;
220			final AuthMode authMode;
221	
222			ProgrammaticRouteRule(String id, List<String> paths, List<String> methods, AuthMode authMode) {
223				this.id = id;
224				this.paths = paths != null ? paths : Collections.emptyList();
225				this.methods = methods != null ? methods : Collections.emptyList();
226				this.authMode = authMode;
227			}
228		}
229	
230		/**
231		/**
232		 * Adapter that bridges a string path to {@link org.springframework.http.server.PathContainer}
233		 * without requiring the spring-web dependency at the API level.
234		 */
235		private static final class PathContainerAdapter {
236			private PathContainerAdapter() {}
237	
238			static org.springframework.http.server.PathContainer parse(String path) {
239				return org.springframework.http.server.PathContainer.parsePath(path);
240			}
241		}
242	}
